/**
 * 클릭된 값의 주소를 검색한다.
 * 
 * @return void
 **/
$.fn.clickPnu = function(pix){
	if(mapObj["zoom"]<16){
		return;
	}
	
	if($("div.map_right02 ul li a.i01").hasClass("on") || $("div.map_right03 ul li a.i01").hasClass("on") || $("div.map_right03 ul li a.i02").hasClass("on")){
		return;
	}
	
	var coord = map.getCoordinateFromPixel(pix);
	var jsonurl = server+"/MapPlan?req=search";
	var params = {
			version: mapObj["version"],
			layer:"FA",
			mbr: coord[0] +','+ coord[1]+','+coord[0]+','+coord[1]
	};
	$.getJSON(jsonurl,params,function(data, status) {
		var features = new ol.format.GeoJSON().readFeatures(data);
		if(features.length > 0){
			var feature = features[0];
			var att = feature.getProperties();
			var pnu = att.pnu;

			$.ajax({
				type:"POST", 
		    	url: context+"/mp/mpMapDetGisAjaxXml.jsp",
		    	dataType:"json",  
		    	data:{
		    		"sId" : "selectPrePnuConvert",
		    		"keyword" : pnu
		    	},
		    	error:function(){   
			        //console.log("예상치 못한 에러가 발생하였습니다.");   
			    }, 
		        success : function(data){
		        	$.fn.choiceGisAddr(null, data.pnu, false, true, coord, pnu);
		        },
		        complete : function(){
		        	addrSearcgFlag=true;
		        }
		    });
		}
	});
}


$.fn.leftLayerCont = function(){
	$(".subj ul li em").removeClass("disable");
	if(mapObj["zoom"]<12){
		$(".subj ul li em.type0").addClass("disable");
		$(".subj ul li em.typeA").addClass("disable");
		$(".subj ul li em.typeB").addClass("disable");
		$(".subj ul li em.typeC").addClass("disable");
	}else if(12<=mapObj["zoom"] && mapObj["zoom"] <=15){
		$(".subj ul li em.type0").addClass("disable");
		$(".subj ul li em.typeA").addClass("on");
		$(".subj ul li em.typeB").addClass("disable");
		$(".subj ul li em.typeC").addClass("disable");
	}else if(16<=mapObj["zoom"] ){
		if($(".subj ul li em.type0").hasClass("on")){
			$(".subj ul li em.typeA").removeClass("on");
		}
	}
}


$.fn.removeVector = function(name){
	if(name=="searchLcstVector"){
		if(mapObj["featuresLcst"]!=null){
			for(var i=0 ; i<mapObj["featuresLcst"].length ; i++){
				searchLcstSource.removeFeature(mapObj["featuresLcst"][i]);
			}
			mapObj["featuresLcst"]=null;
		}
		webMapData("removeLcst",null,null);
	}
}
