$.fn.selectGisAddrList = function(obj){
	var keyword=$(obj).val();
	keyword=keyword.replace("번지", "");
	keyword=keyword.trimGis();
	var chkFlag=$.fn.chkGisKeyword(keyword);
	
	if(!chkFlag){
		addrSearcgFlag=true;
		return;
	} 
		
	$.fn.selectGisAddrListSubmit(keyword);
}


/**
 * 서버에서 주소를 검색한다
 * 
 * @param
 * @return
 **/
$.fn.changeGisSearchKeyword = function(keyword){
	if(typeof keyword == "string"){
		keyword=keyword.replace(/전남광주통합(?!특별시)/g, "전남광주통합특별시");
	}
	return keyword;
}

$.fn.selectGisAddrListSubmit = function(keyword){
	keyword=$.fn.changeGisSearchKeyword(keyword);
	$.ajax({
		type:"POST", 
    	url: context+"/mp/mpMapDetGisAjaxXml.jsp",
    	dataType:"json",  
    	data:{
    		"sId" : "selectGisAddrList",
    		"keyword" : keyword
    	},
    	error:function(){   
	        //console.log("예상치 못한 에러가 발생하였습니다.");   
	    }, 
        success : function(data){
        	$.fn.makeGisAddrHtml(data, keyword);
        },
        complete : function(){
        	addrSearcgFlag=true;
        }
    });
}

