	var jsonurl = server+"/MapPlan?req=search";
	var params = {
		version: mapObj["version"],
		layer:"FA",
		mbr: center[0]+","+center[1]+","+center[0]+","+center[1]
	};
	$.getJSON(jsonurl,params,function(data, status) {
		if(data!=null){
			var zoom=map.getView().getZoom();
			var pnu="";
			var addr=""
			if(data.features[0]!=null){
				
				if(7<=zoom && zoom<=8){
					addr="대한민국";
				}else if(9<=zoom && zoom<=11){
					pnu=data.features[0].properties.pnu;
					pnu=pnu.substring(0,2);
				}else if(12<=zoom && zoom<=13){
					pnu=data.features[0].properties.pnu;
					pnu=pnu.substring(0,5);
				}else if(14<=zoom && zoom<=16){
					pnu=data.features[0].properties.pnu;
					pnu=pnu.substring(0,8);
				}else if(17<=zoom && zoom<=18){
					pnu=data.features[0].properties.pnu;
					pnu=pnu.substring(0,10);
				}else {
					pnu=data.features[0].properties.pnu;
				}
				$.ajax({
					type:"POST", 
					url: context+"/mp/mpMapDetGisAjaxXml.jsp",
					dataType:"json",  
					data:{
						"sId" : "selectGisPnuAddr",
						"pnu" : pnu
					},
					error:function(){   
						//console.log("예상치 못한 에러가 발생하였습니다.");   
					}, 
					success : function(data){
						var addrList = $.xml2json(data.addrList, true);
						if(addrList.node!=null){
							addr=addrList.node[0].addr[0].text;
						}
						$("div.map01 span.address").html(addr+" 일대");
					},
					complete : function(){
					}
				});
			}
		}
		
	}).error(function() {
		alert("현재 지도를 업데이트하고 있어 도면서비스를 이용할 수가 없습니다. 창을 닫은 후 새로 접속하시기 바랍니다."); 
	});
