		$(".subj ul li em.type0").addClass("disable");
		$(".subj ul li em.typeA").addClass("disable");
		$(".subj ul li em.typeB").addClass("disable");
		$(".subj ul li em.typeC").addClass("disable");
	}else if(12<=mapObj["zoom"] && mapObj["zoom"] <=15){
		$(".subj ul li em.type0").addClass("disable");
		$(".subj ul li em.typeA").addClass("on");
		$(".subj ul li em.typeB").addClass("disable");
		$(".subj ul li em.typeC").addClass("disable");
