$.fn.selectGisAddrList = function(obj){
	var keyword=$(obj).val();
	keyword=keyword.replace("번지", "");
	keyword=keyword.trimGis();
	var chkFlag=$.fn.chkGisKeyword(keyword);
	
	if(!chkFlag){
		addrSearcgFlag=true;
		return;
	} 
		
	$.fn.selectGisAddrListSubmit(keyword);
}


/**
 * 서버에서 주소를 검색한다
 * 
 * @param
 * @return
 **/
$.fn.changeGisSearchKeyword = function(keyword){
	if(typeof keyword == "string"){
		keyword=keyword.replace(/전남광주통합(?!특별시)/g, "전남광주통합특별시");
	}
	return keyword;
}

